import math

# Basic structure and domain checks
required = ['alpha', 'p_num', 'p_den', 'c_num', 'c_den', 'theta']
for key in required:
    if key not in assign:
        # Missing key
        return (False, None)
alpha = assign['alpha']
p_num = assign['p_num']
p_den = assign['p_den']
c_num = assign['c_num']
c_den = assign['c_den']
theta = assign['theta']
# Type checks
if not all(isinstance(v, int) for v in [alpha, p_num, p_den, c_num, c_den, theta]):
    # Non-integer parameters
    return (False, None)
if alpha < 3 or p_den <= 0 or c_den <= 0 or theta <= 0:
    # Invalid domain
    return (False, None)
r = p_num / p_den
c = c_num / c_den
if not (0 < r < 1):
    # r must be in (0,1)
    return (False, None)
if c <= 0:
    # c must be positive
    return (False, None)
base = c + 1.0 / alpha
if base <= 0:
    # Avoid undefined exponentiation
    return (False, None)

# Compute the exact minimal constant K and the minimal integer answer k
K = base ** (-r)
val = theta * K
# Ceil with small tolerance to avoid float corner cases
k = int(math.ceil(val - 1e-12))

# Difficulty enforcement: non-trivial scale and avoid borderline integer K*theta
frac = val - math.floor(val)
if not (0.05 < frac < 0.95):
    # Too close to integer, trivial rounding may weaken minimality checks
    return (False, None)
if not (300 <= k <= 9000):
    return (False, None)

# Minimality and correctness checks via the extremal equal-vector case
# For x_i = 1 for all i, S = alpha. LHS equals alpha / (1 + c * alpha)^r.
S = float(alpha)
LHS_equal = alpha / ((1.0 + c * alpha) ** r)
RHS_k = (k / theta) * (S ** (1.0 - r))
RHS_km1 = ((k - 1) / theta) * (S ** (1.0 - r))

# The inequality should hold with k
if LHS_equal > RHS_k + 1e-9:
    # Incorrect k
    return (False, None)
# Minimality: it should fail with k - 1 at the equal vector (since ceil)
if LHS_equal <= RHS_km1 + 1e-9:
    # Not minimal; either parameters degenerate or rounding error too large
    return (False, None)

# Optional extra randomized sanity check for correctness
# Generate a random positive vector and verify inequality holds with k
import random
x = [random.uniform(0.2, 3.0) for _ in range(alpha)]
Sx = sum(x)
LHS_rand = sum(xi / ((xi + c * Sx) ** r) for xi in x)
RHS_rand = (k / theta) * (Sx ** (1.0 - r))
if LHS_rand > RHS_rand + 1e-7:
    return (False, None)

return (True, k)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

